80	function buildStructurePrompt(answers: GeneratorIntakeAnswers): string {
81	  const flightLessons = Math.ceil(
82	    (answers.totalFlightHours * 60) / answers.flightLessonDurationMin,
83	  );
84	  const groundLessons = Math.ceil(
85	    (answers.totalGroundHours * 60) / answers.groundLessonDurationMin,
86	  );
87	  const simLessons =
88	    answers.simHours > 0 && answers.simLessonDurationMin > 0
89	      ? Math.ceil((answers.simHours * 60) / answers.simLessonDurationMin)
90	      : 0;
91	  const stageChecks = answers.includeStageChecks ? answers.stageCount : 0;
92	  const totalModules = flightLessons + groundLessons + simLessons + stageChecks;
93	
94	  return `You are an expert FAA-certified flight training curriculum designer.
