305	/**
306	 * POST /ai-curriculum-gen/structure
307	 *
308	 * Phase 1: Synchronous structure generation.
309	 * Takes intake answers and returns the complete curriculum structure
310	 * (stages + module titles only, no content) in ~3-6 seconds.
311	 *
312	 * Body: { answers: GeneratorIntakeAnswers }
313	 * Returns: GeneratorStructure JSON
314	 */
315	aiCurriculumGenerator.post(
316	  '/ai-curriculum-gen/structure',
317	  requireAuth(),
318	  async (c) => {
319	    if (!getAnthropicKey('curriculum-generator-build')) {
320	      return c.json({ error: 'AI service not configured' }, 503);
321	    }
322	
323	    let body: { answers?: GeneratorIntakeAnswers };
324	    try {
325	      body = await c.req.json();
326	    } catch {
327	      return c.json({ error: 'Invalid request body' }, 400);
328	    }
329	
330	    if (!body.answers) {
331	      return c.json({ error: 'answers is required' }, 400);
332	    }
333	
334	    const authUser = c.get('authUser') as AuthUser;
335	    const orgId = await resolveOrgIdFromSession(authUser, c);
336	    if (!orgId) return c.json({ error: 'Could not resolve organization' }, 403);
337	
338	    const prompt = buildStructurePrompt(body.answers);
339	
340	    const res = await fetch('https://api.anthropic.com/v1/messages', {
341	      method: 'POST',
342	      headers: {
343	        'Content-Type': 'application/json',
344	        'x-api-key': getAnthropicKey('curriculum-generator-build') ?? '',
345	        'anthropic-version': '2023-06-01',
346	      },
347	      body: JSON.stringify({
348	        model: ANTHROPIC_MODEL,
349	        max_tokens: 8192,
350	        messages: [{ role: 'user', content: prompt }],
351	      }),
352	    });
353	
354	    if (!res.ok) {
355	      const errText = await res.text().catch(() => '');
356	      return c.json(
357	        { error: `AI service error ${res.status}: ${errText}` },
358	        502,
359	      );
360	    }
361	
362	    const data = (await res.json()) as {
363	      content?: Array<{ type: string; text?: string }>;
364	      stop_reason?: string;
365	    };
366	    const raw =
367	      data.content?.find((b) => b.type === 'text')?.text?.trim() ?? '';
368	
369	    if (data.stop_reason === 'max_tokens') {
370	      console.warn(
371	        '[ai-curriculum-gen/structure] Response hit max_tokens limit — attempting repair',
372	      );
373	    }
374	
375	    let structure: GeneratorStructure;
376	    try {
377	      const cleaned = raw
378	        .replace(/^```(?:json)?\n?/m, '')
379	        .replace(/\n?```$/m, '')
380	        .trim();
381	      structure = safeParseAIJson<GeneratorStructure>(cleaned);
382	    } catch {
383	      return c.json(
384	        { error: 'AI returned invalid JSON structure — please try again' },
385	        422,
386	      );
387	    }
388	
389	    if (!structure.stages || !Array.isArray(structure.stages)) {
390	      return c.json(
391	        {
392	          error: 'AI returned invalid curriculum structure — please try again',
393	        },
394	        422,
395	      );
396	    }
397	
398	    // Normalize: add module keys for client-side tracking
399	    let moduleSeq = 0;
400	    for (const stage of structure.stages) {
401	      for (const mod of stage.modules ?? []) {
402	        moduleSeq++;
403	        (mod as GeneratorStructureModule & { key: string }).key =
404	          `s${stage.number}-m${mod.number ?? moduleSeq}`;
405	      }
406	    }
407	
408	    return c.json({ structure });
409	  },
410	);
411	
412	/**
413	 * POST /ai-curriculum-gen/module-stream
414	 *
415	 * Phase 2: Per-module SSE streaming.
416	 * Streams the complete content for ONE module (topics, assignments, resources,
417	 * tasks, regulations, endorsements) as server-sent events.
418	 *
419	 * Body: {
420	 *   answers: GeneratorIntakeAnswers,
421	 *   structureTitle: string,
422	 *   stageNumber: number,
423	 *   stageTitle: string,
424	 *   module: GeneratorStructureModule,
425	 * }
426	 *
427	 * SSE events:
428	 *   { type: 'chunk', text: string }    — raw delta text
429	 *   { type: 'done' }                   — stream complete
430	 *   { type: 'error', error: string }   — generation failed
431	 *   { type: 'heartbeat' }              — keepalive
432	 */
433	aiCurriculumGenerator.post(
434	  '/ai-curriculum-gen/module-stream',
435	  requireAuth(),
436	  async (c) => {
437	    if (!getAnthropicKey('curriculum-generator-refine')) {
438	      return c.json({ error: 'AI service not configured' }, 503);
439	    }
440	
441	    let body: {
442	      answers?: GeneratorIntakeAnswers;
443	      structureTitle?: string;
444	      stageNumber?: number;
445	      stageTitle?: string;
446	      module?: GeneratorStructureModule;
447	    };
448	    try {
449	      body = await c.req.json();
450	    } catch {
451	      return c.json({ error: 'Invalid request body' }, 400);
452	    }
453	
454	    if (
455	      !body.answers ||
456	      !body.structureTitle ||
457	      !body.module ||
458	      body.stageNumber == null
459	    ) {
460	      return c.json(
461	        {
462	          error:
463	            'answers, structureTitle, stageNumber, and module are required',
464	        },
465	        400,
466	      );
467	    }
468	
469	    const authUser = c.get('authUser') as AuthUser;
470	    const orgId = await resolveOrgIdFromSession(authUser, c);
471	    if (!orgId) return c.json({ error: 'Could not resolve organization' }, 403);
472	
473	    const {
474	      answers,
475	      structureTitle,
476	      stageNumber,
477	      stageTitle = '',
478	      module,
479	    } = body;
480	
481	    const prompt = buildModuleStreamPrompt(
482	      answers,
483	      structureTitle,
484	      stageTitle,
485	      stageNumber,
486	      module,
487	      answers.topicsPerModule,
488	      answers.assignmentsPerModule,
489	      answers.resourcesPerModule,
490	      answers.tasksPerModule,
491	    );
492	
493	    const abortSignal = c.req.raw.signal;
494	    const encoder = new TextEncoder();
495	
496	    const stream = new ReadableStream({
497	      async start(controller) {
498	        let closed = false;
499	
500	        function emit(payload: Record<string, unknown>) {
501	          if (closed || abortSignal?.aborted) return;
502	          try {
503	            controller.enqueue(
504	              encoder.encode(`data: ${JSON.stringify(payload)}\n\n`),
505	            );
506	          } catch {
507	            closed = true;
508	          }
509	        }
510	
511	        function safeClose() {
512	          if (!closed) {
513	            closed = true;
514	            try {
515	              controller.close();
516	            } catch {}
517	          }
518	        }
519	
520	        const heartbeat = setInterval(() => emit({ type: 'heartbeat' }), 10000);
521	
522	        try {
523	          const anthropicRes = await fetch(
524	            'https://api.anthropic.com/v1/messages',
525	            {
526	              method: 'POST',
527	              headers: {
528	                'Content-Type': 'application/json',
529	                'x-api-key':
530	                  getAnthropicKey('curriculum-generator-refine') ?? '',
531	                'anthropic-version': '2023-06-01',
532	              },
533	              body: JSON.stringify({
534	                model: ANTHROPIC_MODEL,
535	                max_tokens: 8192,
536	                stream: true,
537	                messages: [{ role: 'user', content: prompt }],
538	              }),
539	              signal: abortSignal,
540	            },
541	          );
542	
543	          if (!anthropicRes.ok) {
544	            const errBody = await anthropicRes.text().catch(() => '');
545	            emit({
546	              type: 'error',
547	              error: `API error ${anthropicRes.status}: ${errBody}`,
548	            });
549	            safeClose();
550	            return;
551	          }
552	
553	          const reader = anthropicRes.body?.getReader();
554	          if (!reader) {
555	            emit({ type: 'error', error: 'No response body from AI' });
556	            safeClose();
557	            return;
558	          }
